INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'bfc4b649-4917-5fe2-9825-b1c5ee2bd244', '01dc2fd5-9c95-53db-b97a-f9de837471c1',
  'Một danh sách được hiện thực bằng **mảng động**, phát biểu nào sau đây đúng khi nói về việc sử dụng phương thức `checkIndex` (phương thức kiểm tra tính hợp lệ của chỉ số)?

Select one or more:

Lựa chọn:
- Trong phương thức thêm, ta chỉ cần sử dụng phương thức `checkIndex` là đủ để xác định tính hợp lệ của chỉ số khi thực hiện thêm phần tử ở vị trí chỉ số tương ứng vào danh sách
- Khi sử dụng phương thức chỉnh sửa dữ liệu của phần tử ở vị trí chỉ số tương ứng, ta cần sử dụng phương thức `checkIndex`
- Khi sử dụng phương thức lấy dữ liệu của phần tử ở vị trí chỉ số tương ứng, ta không cần sử dụng phương thức `checkIndex`
- Trong phương thức xóa, ta chỉ cần sử dụng phương thức `checkIndex` là đủ để xác định tính hợp lệ của chỉ số khi thực hiện xóa phần tử ở vị trí chỉ số tương ứng ra khỏi danh sách
- Khi hiện thực phương thức kiểm tra sự tồn tại của phần tử trong danh sách, ta không cần sử dụng phương thức `checkIndex`', 1
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '5acbf43f-7ffb-5951-bea5-ac0e43ceca1e', '01dc2fd5-9c95-53db-b97a-f9de837471c1',
