INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'b1133dc9-2d52-5a63-b7a7-4679fbbccbe7', '01dc2fd5-9c95-53db-b97a-f9de837471c1',
  'Cho một danh sách liên kết đôi như sau: 1-2-3-4-5. Con trỏ `head` chứa địa chỉ của nút có giá trị 1, con trỏ `tail` chứa địa chỉ của nút có giá trị 5.

Danh sách thu được sau khi thực hiện đoạn mã giả sau trên danh sách ban đầu?

Lưu ý: Các giá trị được ngăn cách bởi dấu gạch ngang "-", không chứa bất kỳ ký tự khoảng trắng.

```text
temp = Node(6, head, head.next);
temp1 = Node(0, tail.previous, tail);
head.next = temp;
temp.next.previous = temp;
tail.previous = temp1;
temp1.previous.next = temp1;
```', 12
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '77725cda-6aa2-5d85-9717-dc3dbe7e5dea', '01dc2fd5-9c95-53db-b97a-f9de837471c1',
  '**Dữ liệu được sử dụng cho câu hỏi:**

Cho sơ đồ bố trí con trỏ trên một danh sách liên kết hiện tại được viết bằng mã giả sau:

```text
head = Node(30)
temp1 = Node(17), head.next = temp1
temp2 = Node(42), temp1.next = temp2
tail = temp2
```

Đoạn mã giả nào dưới đây dùng để thêm một phần tử mang giá trị 18 vào cuối danh sách?

Lựa chọn:
- A
```text
head = tail = Node(18)
tail.next = NULL
```
- B.
```text
temp2.next = Node(18)
tail = temp2.next
```
- C.
```text
temp = Node(18)
temp1.next = temp1
tail = temp
```
- D
```text
tail = Node(18)
temp2 = tail
```
- E
```text
temp = Node(18)
tail = temp
temp.next = temp2
```', 13
);

