INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '50db6804-6b16-5dca-82ed-533d334cfb92', '01dc2fd5-9c95-53db-b97a-f9de837471c1',
  'Đoạn mã nào sau đây hiện thực cho thao tác nối danh sách `list1` vào một danh sách và sau đó làm trống danh sách `list1`? Select one:

Lựa chọn:
- **A.**
```text
if (head == NULL)
    head = list1->head;
else {
    p = head;
    while (p->next != NULL)
        p = p->next;
    p->next = list1->head;
}
count = list1->count;
list1->count = 0;
list1->head = NULL;
```
- **B.**
```text
if (head == NULL)
    head = list1->head;
else {
    p = head;
    while (p->next != NULL)
        p = p->next;
    p->next = list1->head;
}
count += list1->count;
list1->count = 0;
list1->head = NULL;
```
- **C.**
```text
if (list1->head == NULL)
    list1->head = head;
else {
    p = list1->head;
    while (p->next != NULL)
        p = p->next;
    p->next = head;
}
count += list1->count;
list1->count = 0;
list1->head = NULL;
```
- **D.**
```text
if (list1->head == NULL)
    head = list1->head;
else {
    p = list1->head;
    while (p->next != NULL)
        p = p->next;
    p->next = head;
}
count = list1->count;
