INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '7cebf59b-759e-5c01-bd1e-aad1077c2be8', '01dc2fd5-9c95-53db-b97a-f9de837471c1',
  'Cho đoạn mã được viết bằng ngôn ngữ C++ như sau:

```cpp
class IntDLinkedList {
struct Node {
    int data;
    Node* next;
    Node* prev;
};
private:
    Node* head;
    Node* tail;
public:
    int function() {
        Node* temp = tail->prev;
        tail->prev = temp->prev;
        temp->prev->next = tail;
        count--;
        return temp->data;
    }
};
```

Phương thức `function()` thực hiện.

Select one:

Lựa chọn:
- Xóa phần tử đầu danh sách và trả về dữ liệu của nó
- Xóa phần tử cuối danh sách và trả về dữ liệu của nó
- Trả về dữ liệu của phần tử kế cuối và xóa nó khỏi danh sách
- Trả về dữ liệu của phần tử kế cuối nhưng không xóa nó khỏi danh sách
- Xóa phần tử cuối danh sách nhưng không trả về dữ liệu của nó', 35
);

